                cell.bold = true;
                cell.textAlign = "center";
            });
            return;
        }

        if (row.type === "header") return;

        // Apply alignment from map (by index) + clean values
        row.cells.forEach(function (cell, index) {
            if (cell.value !== null && cell.value !== undefined) {
                var cleanValue = cell.value
                    .toString()
                    .replace(/<[^>]*>/g, "")
                    .replace(/&nbsp;/g, "")
                    .trim();
                cell.value = cleanValue;
                // Use map; default to center if index not in map
                cell.textAlign = alignMap[index] || "center";
            }
        });
    });
}
```

---

## Why this works

| Step | What it does |
|------|--------------|
| **1. Leaf header only** | `headerRows[headerRows.length - 1]` gets the bottom-most header row (actual column headers like `33/100`, `Special`, `Grace`, `Cond.`, `Final`, `%`, `Grade`, `Result`, `Rank`) |
| **2. Build map once** | `alignMap[index] = (headerText === "%") ? "left" : "center"` — no per-row header lookup |
| **3. Apply by index** | `cell.textAlign = alignMap[index] || "center"` — data row index directly maps to header index |

This eliminates the index-drift problem entirely. The `%` column gets left; **all others (including Grace) get center**.

